const options = [
  { value: "email",             label: "Email",              icon: "✉️" },
  { value: "sms",               label: "SMS",                icon: "💬" },
  { value: "push_notifications", label: "Push Notifications", icon: "🔔" },
];

// Component: RadioOption
function RadioOption({ option, selected, onChange }) {
  const isSelected = selected === option.value;

  const el = document.createElement("label");
  el.className = "radio-option" + (isSelected ? " selected" : "");
  el.setAttribute("aria-checked", isSelected);

  const input = document.createElement("input");
  input.type = "radio";
  input.name = "notification";
  input.value = option.value;
  input.checked = isSelected;
  input.addEventListener("change", () => onChange(option.value));

  const radioCustom = document.createElement("span");
  radioCustom.className = "radio-custom";
  const dot = document.createElement("span");
  dot.className = "radio-dot";
  radioCustom.appendChild(dot);

  const icon = document.createElement("span");
  icon.className = "radio-icon";
  icon.textContent = option.icon;

  const labelText = document.createElement("span");
  labelText.className = "radio-label";
  labelText.textContent = option.label;

  el.appendChild(input);
  el.appendChild(radioCustom);
  el.appendChild(icon);
  el.appendChild(labelText);

  return el;
}

// Component: NotificationForm
function NotificationForm({ selected, onChange, onSubmit, submitted }) {
  const app = document.createElement("div");
  app.className = "app";

  const card = document.createElement("div");
  card.className = "card";

  // Header
  const header = document.createElement("div");
  header.className = "card-header";
  const h1 = document.createElement("h1");
  h1.textContent = "Preferences";
  const subtitle = document.createElement("p");
  subtitle.textContent = "Customize how you stay in the loop.";
  header.appendChild(h1);
  header.appendChild(subtitle);

  // Form
  const form = document.createElement("form");
  form.noValidate = true;
  form.addEventListener("submit", (e) => {
    e.preventDefault();
    onSubmit();
  });

  // Form field
  const formField = document.createElement("fieldset");
  formField.className = "form-field";
  formField.style.border = "none";

  const legend = document.createElement("legend");
  legend.textContent = "How do you prefer to receive notifications?";
  formField.appendChild(legend);

  options.forEach((opt) => {
    formField.appendChild(RadioOption({ option: opt, selected, onChange }));
  });

  // Submit button
  const btn = document.createElement("button");
  btn.type = "submit";
  btn.className = "submit-btn";
  btn.textContent = "Save Preference";
  btn.disabled = !selected;

  // Success banner
  const banner = document.createElement("div");
  banner.className = "success-banner" + (submitted ? " visible" : "");
  banner.innerHTML = "✓ &nbsp;Your preference has been saved!";

  form.appendChild(formField);
  form.appendChild(btn);
  form.appendChild(banner);

  card.appendChild(header);
  card.appendChild(form);
  app.appendChild(card);

  return app;
}

// App state
let state = { selected: null, submitted: false };

function render() {
  const root = document.getElementById("root");
  root.innerHTML = "";

  const el = NotificationForm({
    selected: state.selected,
    submitted: state.submitted,
    onChange(value) {
      state = { selected: value, submitted: false };
      render();
    },
    onSubmit() {
      if (!state.selected) return;
      state = { ...state, submitted: true };
      render();
    },
  });

  root.appendChild(el);
}

render();
